create table if not exists private.titan_coach_programs (
  id uuid primary key default gen_random_uuid(),
  coach_id uuid not null references auth.users(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 100),
  version integer not null default 1 check (version >= 1),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists titan_coach_programs_coach_idx on private.titan_coach_programs (coach_id, updated_at desc);
create table if not exists private.titan_coach_program_versions (
  program_id uuid not null references private.titan_coach_programs(id) on delete cascade,
  version integer not null check (version >= 1),
  weeks smallint not null check (weeks between 1 and 12),
  goals jsonb not null default '[]'::jsonb check (jsonb_typeof(goals) = 'array' and jsonb_array_length(goals) <= 5),
  sessions jsonb not null check (jsonb_typeof(sessions) = 'array' and jsonb_array_length(sessions) between 1 and 60),
  created_at timestamptz not null default now(),
  primary key (program_id, version)
);
create table if not exists private.titan_coach_plans (
  id uuid primary key default gen_random_uuid(),
  link_id uuid not null references public.coach_links(id) on delete cascade,
  coach_id uuid not null references auth.users(id) on delete cascade,
  program_id uuid references private.titan_coach_programs(id) on delete set null,
  program_version integer,
  basis jsonb not null check (jsonb_typeof(basis) = 'object' and basis->>'kind' in ('program', 'plan')),
  title text not null check (char_length(title) between 1 and 100),
  goals jsonb not null default '[]'::jsonb check (jsonb_typeof(goals) = 'array' and jsonb_array_length(goals) <= 5),
  start_date date not null check (extract(isodow from start_date) = 1 and start_date between '2000-01-03' and '2100-12-27'),
  weeks smallint not null check (weeks between 1 and 12),
  sessions jsonb not null check (jsonb_typeof(sessions) = 'array' and jsonb_array_length(sessions) between 1 and 60),
  state text not null default 'draft' check (state in ('draft', 'sent', 'closed', 'discarded')),
  version integer not null default 0,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sent_at timestamptz,
  closed_at timestamptz,
  check ((state in ('sent', 'closed')) = (sent_at is not null)),
  check ((state = 'closed') = (closed_at is not null))
);
create index if not exists titan_coach_plans_link_idx on private.titan_coach_plans (link_id, created_at desc);
create index if not exists titan_coach_plans_program_idx on private.titan_coach_plans (program_id);
create table if not exists private.titan_coach_plan_versions (
  plan_id uuid not null references private.titan_coach_plans(id) on delete cascade,
  version integer not null check (version >= 1),
  kind text not null check (kind in ('sent', 'revision', 'closed')),
  op_id uuid,
  scope text check (scope is null or scope in ('occurrence', 'week', 'rest')),
  summary jsonb not null default '{}'::jsonb check (jsonb_typeof(summary) = 'object'),
  snapshot jsonb not null check (jsonb_typeof(snapshot) = 'array'),
  actor uuid,
  created_at timestamptz not null default now(),
  primary key (plan_id, version)
);
create unique index if not exists titan_coach_plan_versions_op on private.titan_coach_plan_versions (plan_id, op_id) where op_id is not null;
alter table private.titan_coach_programs enable row level security;
alter table private.titan_coach_program_versions enable row level security;
alter table private.titan_coach_plans enable row level security;
alter table private.titan_coach_plan_versions enable row level security;
revoke all on private.titan_coach_programs, private.titan_coach_program_versions, private.titan_coach_plans, private.titan_coach_plan_versions from public, anon, authenticated;

