-- The sessions of a template or of a programme: week (1..weeks), day (1 = Monday .. 7), name, sport of the catalogue, instructions, and a
-- stable key that follows the session through drafts, sends and revisions. Ordered by week, day and key.
create or replace function private.titan_coach_program_sessions(p jsonb, p_weeks integer)
returns jsonb language plpgsql volatile security definer set search_path = ''
as $function$
declare v_out jsonb := '[]'::jsonb; e jsonb; v_key text; v_week integer; v_day integer; v_title text; v_keys text[] := '{}';
begin
  if jsonb_typeof(p) is distinct from 'array' or jsonb_array_length(p) = 0 or jsonb_array_length(p) > 60 then raise exception 'BAD_SESSIONS' using errcode = '22023'; end if;
  for e in select x from jsonb_array_elements(p) x loop
    if jsonb_typeof(e) is distinct from 'object' then raise exception 'BAD_SESSIONS' using errcode = '22023'; end if;
    begin v_week := (e->>'week')::integer; v_day := (e->>'day')::integer; exception when others then raise exception 'BAD_SESSIONS' using errcode = '22023'; end;
    if v_week is null or v_week < 1 or v_week > p_weeks or v_day is null or v_day < 1 or v_day > 7 then raise exception 'BAD_SESSIONS' using errcode = '22023'; end if;
    v_key := coalesce(nullif(e->>'key', ''), 'n' || left(md5(gen_random_uuid()::text), 10));
    if v_key !~ '^[A-Za-z0-9_-]{1,32}$' or v_key = any(v_keys) then raise exception 'BAD_SESSIONS' using errcode = '22023'; end if;
    v_keys := v_keys || v_key;
    v_title := left(regexp_replace(btrim(coalesce(e->>'title', '')), '[[:cntrl:]<>]', '', 'g'), 100);
    if v_title = '' then raise exception 'BAD_TITLE' using errcode = '22023'; end if;
    if not exists (select 1 from public.sports s where s.id = e->>'sport' and coalesce(s.is_active, true)) then raise exception 'SPORT_UNKNOWN' using errcode = '22023'; end if;
    v_out := v_out || jsonb_build_array(jsonb_build_object('key', v_key, 'week', v_week, 'day', v_day, 'title', v_title, 'sport', e->>'sport',
      'instructions', left(regexp_replace(coalesce(e->>'instructions', ''), '[\x01-\x09\x0b-\x1f\x7f<>]', '', 'g'), 2000)));
  end loop;
  return (select jsonb_agg(x order by (x->>'week')::integer, (x->>'day')::integer, x->>'key') from jsonb_array_elements(v_out) x);
end;
$function$;
revoke all on function private.titan_coach_program_sessions(jsonb, integer) from public, anon, authenticated;

-- Goals of a cycle: up to 5 short sentences, empty ones dropped.
create or replace function private.titan_coach_program_goals(p jsonb)
returns jsonb language plpgsql immutable set search_path = ''
as $function$
declare v jsonb;
begin
  if p is null or p = 'null'::jsonb then return '[]'::jsonb; end if;
  if jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 5 then raise exception 'BAD_GOALS' using errcode = '22023'; end if;
  select coalesce(jsonb_agg(g order by i), '[]'::jsonb) into v from (
    select left(btrim(regexp_replace(e #>> '{}', '[[:cntrl:]<>]', '', 'g')), 140) g, i from jsonb_array_elements(p) with ordinality x(e, i)
     where jsonb_typeof(e) = 'string') q where g <> '';
  return v;
end;
$function$;
revoke all on function private.titan_coach_program_goals(jsonb) from public, anon, authenticated;

-- The preview of an adaptation: what differs from its starting point, session by session (added, removed, changed and which fields).
create or replace function private.titan_coach_plan_changes(p_base jsonb, p_cur jsonb)
returns jsonb language sql immutable set search_path = ''
as $function$
  select coalesce(jsonb_agg(q.c order by q.w, q.d, q.k), '[]'::jsonb) from (
    select coalesce(a.e->>'key', b.e->>'key') k, coalesce((a.e->>'week')::integer, (b.e->>'week')::integer) w, coalesce((a.e->>'day')::integer, (b.e->>'day')::integer) d,
      jsonb_strip_nulls(jsonb_build_object('key', coalesce(a.e->>'key', b.e->>'key'),
        'kind', case when b.e is null then 'added' when a.e is null then 'removed' else 'changed' end, 'before', b.e, 'after', a.e,
        'fields', case when a.e is not null and b.e is not null then
          (select jsonb_agg(f order by n) from unnest(array['week', 'day', 'title', 'sport', 'instructions']) with ordinality u(f, n) where a.e->>f is distinct from b.e->>f) end)) c
      from (select e from jsonb_array_elements(coalesce(p_base, '[]'::jsonb)) e) b
      full join (select e from jsonb_array_elements(coalesce(p_cur, '[]'::jsonb)) e) a on a.e->>'key' = b.e->>'key'
     where b.e is null or a.e is null
        or exists (select 1 from unnest(array['week', 'day', 'title', 'sport', 'instructions']) f where a.e->>f is distinct from b.e->>f)) q
$function$;
revoke all on function private.titan_coach_plan_changes(jsonb, jsonb) from public, anon, authenticated;

-- What a version keeps of every session of a sent programme: its proposal and its status, never a measure of the journal.
create or replace function private.titan_coach_plan_snapshot(p_plan uuid)
returns jsonb language sql stable security definer set search_path = ''
as $function$
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('key', a.plan_key, 'week', a.plan_week, 'id', a.id, 'title', a.title, 'sport', a.sport,
           'planned_date', a.planned_date, 'moved_date', a.moved_date, 'instructions', a.instructions, 'status', a.status,
           'linked', a.session_id is not null, 'change_pending', a.pending_change is not null, 'discuss', a.discuss_at is not null))
           order by a.plan_week, a.planned_date, a.plan_key), '[]'::jsonb)
    from public.coach_assignments a where a.plan_id = p_plan
$function$;
revoke all on function private.titan_coach_plan_snapshot(uuid) from public, anon, authenticated;

-- The athlete's answer to a change waiting beside the version in force: the V1.9.1 rule (answer_change), shared by the programme.
create or replace function private.titan_coach_apply_change(p_id uuid, p_accept boolean)
returns public.coach_assignments language plpgsql security definer set search_path = ''
as $function$
declare v_a public.coach_assignments%rowtype; v_change jsonb;
begin
  select * into v_a from public.coach_assignments where id = p_id;
  if p_accept then
    v_change := v_a.pending_change;
    update public.coach_assignments set
        title = v_change->>'title', sport = v_change->>'sport', planned_date = (v_change->>'planned_date')::date, instructions = coalesce(v_change->>'instructions', ''),
        moved_date = case when (v_change->>'planned_date')::date is distinct from planned_date then null else moved_date end,
        done_declared_at = case when (v_change->>'planned_date')::date is distinct from planned_date or v_change->>'sport' is distinct from sport then null else done_declared_at end,
        status = 'accepted', pending_change = null, revision = revision + 1, updated_at = now(),
        history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_build_object('k', 'change_accepted', 'at', now(), 'before', private.titan_coach_assignment_version(v_a),
                    'after', v_change - 'note' - 'at' - 'from_status' - 'plan_version')))
     where id = v_a.id returning * into v_a;
  else
    update public.coach_assignments set pending_change = null, revision = revision + 1, updated_at = now(),
      history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_build_object('k', 'change_declined', 'at', now(), 'kept', private.titan_coach_assignment_version(v_a))))
     where id = v_a.id returning * into v_a;
  end if;
  return v_a;
end;
$function$;
revoke all on function private.titan_coach_apply_change(uuid, boolean) from public, anon, authenticated;

-- ---- V1.9.1 row, re-applied with two additive changes: « to_discuss » and the programme of the proposal (everything else unchanged).
create or replace function private.titan_coach_followup_row(a public.coach_assignments, l public.coach_links, p_role text)
returns jsonb language plpgsql stable security definer set search_path = ''
as $function$
declare
  v_today date := (now() at time zone 'Europe/Paris')::date; v_eff date := coalesce(a.moved_date, a.planned_date);
  v_cands jsonb := '[]'::jsonb; v_log public.training_logs%rowtype; v_linked jsonb; v_state text; v_coach text; v_key text;
  v_scope boolean; v_day date; v_gap integer; v_history jsonb := a.history; v_active boolean := l.revoked_at is null and private.titan_coach_link_active(l.id);
  v_plan jsonb;
begin
  if a.status = 'accepted' or (a.status = 'completed' and a.session_id is null) then v_cands := private.titan_coach_match_candidates(a, l); end if;
  if a.session_id is not null then
    select * into v_log from public.training_logs t where t.id = a.session_id;
    v_day := (v_log.date at time zone 'Europe/Paris')::date;
    v_scope := v_log.id is not null and v_log.archived_at is null and (l.sport is null or l.sport = v_log.sport) and v_log.date >= l.since_date::timestamp at time zone 'UTC';
    v_gap := v_day - a.planned_date;
    if p_role = 'athlete' or v_scope then
      v_linked := jsonb_build_object('in_scope', coalesce(v_scope, false), 'day', v_day, 'sport', v_log.sport, 'val', v_log.val, 'unit', v_log.unit, 'archived', v_log.archived_at is not null,
        'duration', case when coalesce(v_log.details->>'duration','') ~ '^[0-9]+([.][0-9]+)?$' then (v_log.details->>'duration')::numeric
                         when coalesce(v_log.details#>>'{gpxStats,movingMinutes}','') ~ '^[0-9]+([.][0-9]+)?$' then (v_log.details#>>'{gpxStats,movingMinutes}')::numeric else null end,
        'session_id', case when p_role = 'athlete' then a.session_id else null end);
    else
      v_linked := jsonb_build_object('in_scope', false);
      v_gap := null;
      v_history := coalesce((select jsonb_agg(e - 'day' order by i) from jsonb_array_elements(a.history) with ordinality x(e, i)), '[]'::jsonb);
    end if;
  end if;
  if a.plan_id is not null then
    select jsonb_build_object('id', p.id, 'title', p.title, 'week', a.plan_week, 'weeks', p.weeks, 'state', p.state, 'key', a.plan_key) into v_plan
      from private.titan_coach_plans p where p.id = a.plan_id;
  end if;
  v_state := case
    when a.status = 'cancelled' then 'cancelled'
    when a.status = 'completed' and a.session_id is not null then 'linked'
    when a.status = 'completed' then case when jsonb_array_length(v_cands) > 0 then 'to_match' else 'done_unmatched' end
    when a.pending_change is not null then 'reproposed'
    when a.status = 'proposed' and a.discuss_at is not null then 'to_discuss'
    when a.status = 'proposed' then 'awaiting'
    when a.status = 'declined' then 'declined'
    when jsonb_array_length(v_cands) > 0 then 'to_match'
    when a.done_declared_at is not null then 'done_unmatched'
    when v_eff < v_today then 'overdue'
    when a.moved_date is not null then 'moved'
    else 'planned' end;
  v_coach := case
    when v_state in ('awaiting', 'reproposed', 'to_match') then 'wait'
    when v_state in ('overdue', 'done_unmatched', 'moved', 'to_discuss') then 'gap'
    when v_state = 'linked' and (v_gap is distinct from 0 or v_scope is not true) then 'gap'
    when v_state in ('declined', 'planned') then 'suggest'
    else 'none' end;
  v_key := left(md5(concat_ws('|', v_state, v_eff, a.session_id, a.done_declared_at, a.pending_change->>'at', a.discuss_at)), 16);
  return jsonb_build_object(
    'id', a.id, 'link_id', a.link_id, 'revision', a.revision, 'status', a.status, 'state', v_state,
    'title', a.title, 'sport', a.sport, 'planned_date', a.planned_date, 'instructions', a.instructions,
    'moved_date', a.moved_date, 'effective_date', v_eff, 'done_date', case when v_linked->>'day' is not null then v_day else null end,
    'gap_days', v_gap, 'done_declared_at', a.done_declared_at, 'created_at', a.created_at, 'updated_at', a.updated_at,
    'accepted_version', a.accepted_version, 'pending_change', a.pending_change, 'linked', v_linked, 'history', v_history,
    'coach_next', case when v_active then v_coach else 'none' end, 'seen', a.coach_seen_key is not distinct from v_key and v_coach = 'gap', 'state_key', v_key,
    'candidates', case when p_role = 'athlete' then v_cands else null end,
    'candidate_count', case when p_role = 'coach' then jsonb_array_length(v_cands) else null end,
    'link_state', case when l.revoked_at is not null then 'revoked' when v_active then 'active' else 'paused' end,
    'can_act', v_active,
    'plan', v_plan, 'discuss_note', a.discuss_note, 'discuss_at', a.discuss_at);
end;
$function$;
revoke all on function private.titan_coach_followup_row(public.coach_assignments, public.coach_links, text) from public, anon, authenticated;

-- A programme as one side sees it. A draft (coach only): its sessions with their dates and the preview against its starting point.
-- Sent or closed: every session read through the V1.9.1 row (the link's contract applies), the counts the coach needs (accepted,
-- waiting, to discuss, linked, declined), and its versions (with their snapshots when p_detail).
create or replace function private.titan_coach_plan_row(p private.titan_coach_plans, l public.coach_links, p_role text, p_detail boolean default false)
returns jsonb language plpgsql stable security definer set search_path = ''
as $function$
declare v_rows jsonb := '[]'::jsonb; v_a public.coach_assignments%rowtype; v_r jsonb; v_active boolean := l.revoked_at is null and private.titan_coach_link_active(l.id);
  v_prog private.titan_coach_programs%rowtype; v_today date := (now() at time zone 'Europe/Paris')::date;
begin
  if p.state in ('sent', 'closed') then
    for v_a in select * from public.coach_assignments a where a.plan_id = p.id order by a.plan_week, a.planned_date, a.plan_key loop
      v_r := private.titan_coach_followup_row(v_a, l, p_role);
      if not p_detail then v_r := v_r - 'history' - 'candidates' - 'accepted_version'; end if;
      v_rows := v_rows || jsonb_build_array(v_r || jsonb_build_object('key', v_a.plan_key, 'week', v_a.plan_week));
    end loop;
  else
    select coalesce(jsonb_agg(e || jsonb_build_object('planned_date', p.start_date + ((e->>'week')::integer - 1) * 7 + (e->>'day')::integer - 1)
             order by (e->>'week')::integer, (e->>'day')::integer, e->>'key'), '[]'::jsonb) into v_rows from jsonb_array_elements(p.sessions) e;
  end if;
  if p.program_id is not null then select * into v_prog from private.titan_coach_programs where id = p.program_id; end if;
  -- Top-level keys without a value are left out (a draft has no versions to show the athlete, the athlete never reads the basis).
  return (select jsonb_object_agg(k, v) from jsonb_each(jsonb_build_object('id', p.id, 'link_id', p.link_id, 'title', p.title, 'goals', p.goals, 'start_date', p.start_date,
    'end_date', p.start_date + p.weeks * 7 - 1, 'weeks', p.weeks, 'state', p.state, 'version', p.version, 'revision', p.revision, 'today', v_today,
    'current_week', case when v_today between p.start_date and p.start_date + p.weeks * 7 - 1 then (v_today - p.start_date) / 7 + 1 else null end,
    'created_at', p.created_at, 'updated_at', p.updated_at, 'sent_at', p.sent_at, 'closed_at', p.closed_at,
    'prep_minutes', case when p.sent_at is not null then round(extract(epoch from p.sent_at - p.created_at) / 60.0, 1) else null end,
    'basis', case when p_role = 'coach' then p.basis - 'sessions' - 'goals' else null end,
    'program', case when p_role = 'coach' and v_prog.id is not null then jsonb_build_object('id', v_prog.id, 'title', v_prog.title, 'version', p.program_version,
                 'current_version', v_prog.version, 'archived', v_prog.archived_at is not null) else null end,
    'changes', case when p_role = 'coach' and p.state = 'draft' then private.titan_coach_plan_changes(p.basis->'sessions', p.sessions) else null end,
    'sessions', v_rows,
    'counts', jsonb_build_object('sessions', jsonb_array_length(v_rows),
      'awaiting', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'awaiting'),
      'to_discuss', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'to_discuss'),
      'accepted', (select count(*) from jsonb_array_elements(v_rows) e where e->>'status' in ('accepted', 'completed')),
      'linked', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'linked'),
      'declined', (select count(*) from jsonb_array_elements(v_rows) e where e->>'status' = 'declined'),
      'cancelled', (select count(*) from jsonb_array_elements(v_rows) e where e->>'status' = 'cancelled'),
      'changes_pending', (select count(*) from jsonb_array_elements(v_rows) e where e->'pending_change' is not null and jsonb_typeof(e->'pending_change') = 'object')),
    'versions', (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('version', v.version, 'kind', v.kind, 'scope', v.scope, 'summary', v.summary, 'created_at', v.created_at,
                   'snapshot', case when p_detail then v.snapshot else null end)) order by v.version), '[]'::jsonb) from private.titan_coach_plan_versions v where v.plan_id = p.id),
    'link_state', case when l.revoked_at is not null then 'revoked' when v_active then 'active' else 'paused' end,
    'can_act', v_active and p.state in ('draft', 'sent'))) x(k, v) where jsonb_typeof(v) <> 'null');
end;
$function$;
revoke all on function private.titan_coach_plan_row(private.titan_coach_plans, public.coach_links, text, boolean) from public, anon, authenticated;

create or replace function public.titan_coach_program_v1(p_action text, p_data jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = '' set statement_timeout = '8s'
as $function$
declare
  v_uid uuid := auth.uid(); v_today date := (now() at time zone 'Europe/Paris')::date; v_link public.coach_links%rowtype; v_role text;
  v_prog private.titan_coach_programs%rowtype; v_pv private.titan_coach_program_versions%rowtype; v_plan private.titan_coach_plans%rowtype;
  v_src private.titan_coach_plans%rowtype; v_a public.coach_assignments%rowtype; v_id uuid; v_weeks integer; v_sessions jsonb; v_goals jsonb;
  v_title text; v_date date; v_basis jsonb; v_e jsonb; v_effects jsonb := '[]'::jsonb; v_scope text; v_key text; v_week integer; v_shift integer;
  v_changes jsonb; v_before jsonb; v_after jsonb; v_effect text; v_note text; v_preview text; v_op uuid; v_results jsonb := '[]'::jsonb;
  v_answer text; v_n integer; v_eff date; v_dry boolean; v_summary jsonb;
begin
  if v_uid is null or not exists (select 1 from public.profiles where id = v_uid and is_suspended is not true) then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text) > 60000 then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
  if not private.titan_flag_on('screens.coach_programs') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  begin
    v_id := nullif(p_data->>'id', '')::uuid;
  exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;

  -- ---- Coach: the library of multi-week templates (current version of each, the number of versions and of programmes made from it).
  if p_action = 'library' then
    return jsonb_build_object('owner', v_uid, 'today', v_today, 'programs', coalesce((
      select jsonb_agg(jsonb_build_object('id', g.id, 'title', g.title, 'version', g.version, 'weeks', v.weeks, 'goals', v.goals, 'sessions', v.sessions,
               'versions', (select count(*) from private.titan_coach_program_versions x where x.program_id = g.id),
               'plans', (select count(*) from private.titan_coach_plans p where p.program_id = g.id and p.state <> 'discarded'), 'updated_at', g.updated_at)
             order by g.updated_at desc, g.id)
        from private.titan_coach_programs g join private.titan_coach_program_versions v on v.program_id = g.id and v.version = g.version
       where g.coach_id = v_uid and g.archived_at is null), '[]'::jsonb));
  end if;

  if p_action = 'program' then
    select * into v_prog from private.titan_coach_programs where id = v_id and coach_id = v_uid;
    if not found then raise exception 'PROGRAM_UNAVAILABLE' using errcode = '22023'; end if;
    return jsonb_build_object('id', v_prog.id, 'title', v_prog.title, 'version', v_prog.version, 'archived', v_prog.archived_at is not null,
      'versions', (select jsonb_agg(jsonb_build_object('version', v.version, 'weeks', v.weeks, 'goals', v.goals, 'sessions', v.sessions, 'created_at', v.created_at) order by v.version)
                     from private.titan_coach_program_versions v where v.program_id = v_prog.id));
  end if;

  -- ---- Coach: save a template. A new one starts at version 1; saving an existing one (with the version read) adds a version.
  if p_action = 'save_program' then
    perform private.titan_rate_limit(v_uid, 'coach_program', 120);
    v_title := left(regexp_replace(btrim(coalesce(p_data->>'title', '')), '[[:cntrl:]<>]', '', 'g'), 100);
    if v_title = '' then raise exception 'BAD_TITLE' using errcode = '22023'; end if;
    begin v_weeks := (p_data->>'weeks')::integer; exception when others then raise exception 'BAD_SESSIONS' using errcode = '22023'; end;
    if v_weeks is null or v_weeks < 1 or v_weeks > 12 then raise exception 'BAD_SESSIONS' using errcode = '22023'; end if;
    v_sessions := private.titan_coach_program_sessions(p_data->'sessions', v_weeks);
    v_goals := private.titan_coach_program_goals(p_data->'goals');
    if v_id is null then
      if (select count(*) from private.titan_coach_programs where coach_id = v_uid and archived_at is null) >= 50 then raise exception 'PROGRAM_LIMIT' using errcode = '22023'; end if;
      insert into private.titan_coach_programs (coach_id, title) values (v_uid, v_title) returning * into v_prog;
    else
      select * into v_prog from private.titan_coach_programs where id = v_id and coach_id = v_uid and archived_at is null for update;
      if not found then raise exception 'PROGRAM_UNAVAILABLE' using errcode = '22023'; end if;
      if v_prog.version is distinct from (p_data->>'version')::integer then raise exception 'COACH_CONFLICT'; end if;
      select * into v_pv from private.titan_coach_program_versions where program_id = v_prog.id and version = v_prog.version;
      if v_pv.weeks = v_weeks and v_pv.goals = v_goals and v_pv.sessions = v_sessions and v_prog.title = v_title then
        return jsonb_build_object('ok', true, 'unchanged', true, 'id', v_prog.id, 'version', v_prog.version);
      end if;
      update private.titan_coach_programs set title = v_title, version = version + 1, updated_at = now() where id = v_prog.id returning * into v_prog;
    end if;
    insert into private.titan_coach_program_versions (program_id, version, weeks, goals, sessions) values (v_prog.id, v_prog.version, v_weeks, v_goals, v_sessions);
    return jsonb_build_object('ok', true, 'id', v_prog.id, 'version', v_prog.version, 'weeks', v_weeks, 'goals', v_goals, 'sessions', v_sessions);
  end if;

  if p_action = 'archive_program' then
    update private.titan_coach_programs set archived_at = coalesce(archived_at, now()), updated_at = now() where id = v_id and coach_id = v_uid returning * into v_prog;
    if not found then raise exception 'PROGRAM_UNAVAILABLE' using errcode = '22023'; end if;
    return jsonb_build_object('ok', true, 'id', v_prog.id);
  end if;

  -- ---- Athlete: the programmes I received, across my links (paused and ended ones read-only, ended ones for a year).
  if p_action = 'athlete' then
    return jsonb_build_object('owner', v_uid, 'today', v_today, 'plans', coalesce((
      select jsonb_agg(private.titan_coach_plan_row(p, l, 'athlete') || jsonb_build_object('coach_name', c.username)
             order by case when l.revoked_at is null and p.state = 'sent' then 0 else 1 end, p.start_date desc, p.id)
        from private.titan_coach_plans p join public.coach_links l on l.id = p.link_id join public.profiles c on c.id = l.coach_id
       where l.athlete_id = v_uid and p.state in ('sent', 'closed') and (l.revoked_at is null or l.revoked_at > now() - interval '365 days')), '[]'::jsonb));
  end if;

  -- ---- One link's programmes (coach: an active link; athlete: any of their links, read-only unless active).
  if p_action = 'link' then
    begin select * into v_link from public.coach_links where id = nullif(p_data->>'link_id', '')::uuid and (coach_id = v_uid or athlete_id = v_uid);
    exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
    if not found or (v_link.coach_id = v_uid and v_link.revoked_at is not null) then raise exception 'SHARING_UNAVAILABLE' using errcode = '42501'; end if;
    v_role := case when v_link.coach_id = v_uid then 'coach' else 'athlete' end;
    if v_role = 'coach' and not private.titan_coach_link_active(v_link.id) then raise exception 'COACH_CAPACITY_PAUSED' using errcode = '42501'; end if;
    return jsonb_build_object('link_id', v_link.id, 'role', v_role, 'link_revision', v_link.revision, 'plans', coalesce((
      select jsonb_agg(private.titan_coach_plan_row(p, v_link, v_role) order by p.start_date desc, p.created_at desc)
        from private.titan_coach_plans p where p.link_id = v_link.id and (case when v_role = 'coach' then p.state <> 'discarded' else p.state in ('sent', 'closed') end)), '[]'::jsonb));
  end if;

  if p_action = 'plan' then
    select l.* into v_link from public.coach_links l join private.titan_coach_plans p on p.link_id = l.id where p.id = v_id and (l.coach_id = v_uid or l.athlete_id = v_uid);
    if not found or (v_link.coach_id = v_uid and v_link.revoked_at is not null) then raise exception 'SHARING_UNAVAILABLE' using errcode = '42501'; end if;
    v_role := case when v_link.coach_id = v_uid then 'coach' else 'athlete' end;
    if v_role = 'coach' and not private.titan_coach_link_active(v_link.id) then raise exception 'COACH_CAPACITY_PAUSED' using errcode = '42501'; end if;
    select * into v_plan from private.titan_coach_plans where id = v_id;
    if v_role = 'athlete' and v_plan.state not in ('sent', 'closed') then raise exception 'SHARING_UNAVAILABLE' using errcode = '42501'; end if;
    if v_role = 'athlete' and v_link.revoked_at is not null and v_link.revoked_at <= now() - interval '365 days' then raise exception 'SHARING_UNAVAILABLE' using errcode = '42501'; end if;
    return private.titan_coach_plan_row(v_plan, v_link, v_role, true);
  end if;

  if p_action not in ('adapt', 'edit', 'discard', 'send', 'revise', 'answer', 'close') then raise exception 'INVALID_ACTION' using errcode = '22023'; end if;

  -- ---- Writes. Lock order of the portal: the sharing link first, then the programme, then its proposals.
  if p_action = 'adapt' then
    begin select * into v_link from public.coach_links where id = nullif(p_data->>'link_id', '')::uuid and revoked_at is null and (coach_id = v_uid or athlete_id = v_uid) for update;
    exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
  else
    select l.* into v_link from public.coach_links l join private.titan_coach_plans p on p.link_id = l.id
     where p.id = v_id and l.revoked_at is null and (l.coach_id = v_uid or l.athlete_id = v_uid) for update of l;
  end if;
  if not found then raise exception 'SHARING_UNAVAILABLE' using errcode = '42501'; end if;
  v_role := case when v_link.coach_id = v_uid then 'coach' else 'athlete' end;
  if p_action = 'answer' and v_role <> 'athlete' then raise exception 'ATHLETE_ONLY' using errcode = '42501'; end if;
  if p_action <> 'answer' and v_role <> 'coach' then raise exception 'COACH_ONLY' using errcode = '42501'; end if;
  if p_action <> 'discard' and not private.titan_coach_link_active(v_link.id) then raise exception 'COACH_CAPACITY_PAUSED' using errcode = '42501'; end if;
  perform private.titan_rate_limit(v_uid, 'coach_program', 120);

  -- adapt: a draft for this athlete, from a template of mine (its current version) or from another programme of mine (another athlete).
  if p_action = 'adapt' then
    if (select count(*) from private.titan_coach_plans where link_id = v_link.id and state <> 'discarded') >= 50 then raise exception 'PLAN_LIMIT' using errcode = '22023'; end if;
    begin v_date := coalesce(nullif(p_data->>'start_date', '')::date, date_trunc('week', v_today)::date + 7);
    exception when others then raise exception 'INVALID_PERIOD' using errcode = '22023'; end;
    if extract(isodow from v_date) <> 1 or v_date < date_trunc('week', v_today)::date or v_date > v_today + 366 then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
    if nullif(p_data->>'program_id', '') is not null then
      begin select * into v_prog from private.titan_coach_programs where id = (p_data->>'program_id')::uuid and coach_id = v_uid and archived_at is null;
      exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
      if v_prog.id is null then raise exception 'PROGRAM_UNAVAILABLE' using errcode = '22023'; end if;
      select * into v_pv from private.titan_coach_program_versions where program_id = v_prog.id and version = v_prog.version;
      v_basis := jsonb_build_object('kind', 'program', 'id', v_prog.id, 'version', v_prog.version, 'title', v_prog.title, 'weeks', v_pv.weeks, 'goals', v_pv.goals, 'sessions', v_pv.sessions);
    elsif nullif(p_data->>'plan_id', '') is not null then
      begin select * into v_src from private.titan_coach_plans where id = (p_data->>'plan_id')::uuid and coach_id = v_uid and state <> 'discarded';
      exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
      if v_src.id is null then raise exception 'PROGRAM_UNAVAILABLE' using errcode = '22023'; end if;
      -- A sent programme is copied as it stands now (revisions included), each session at its week and weekday of the cycle.
      if v_src.state = 'draft' then v_sessions := v_src.sessions;
      else
        select coalesce(jsonb_agg(jsonb_build_object('key', a.plan_key, 'week', least(greatest((a.planned_date - v_src.start_date) / 7 + 1, 1), 12), 'day', extract(isodow from a.planned_date)::integer,
                 'title', a.title, 'sport', a.sport, 'instructions', a.instructions) order by a.plan_week, a.planned_date, a.plan_key), '[]'::jsonb) into v_sessions
          from public.coach_assignments a where a.plan_id = v_src.id;
      end if;
      v_basis := jsonb_build_object('kind', 'plan', 'id', v_src.id, 'title', v_src.title,
        'weeks', greatest(v_src.weeks, (select max((e->>'week')::integer) from jsonb_array_elements(v_sessions) e)), 'goals', v_src.goals, 'sessions', v_sessions,
        'program_id', v_src.program_id, 'program_version', v_src.program_version);
    else raise exception 'PROGRAM_UNAVAILABLE' using errcode = '22023';
    end if;
    v_basis := v_basis || jsonb_build_object('sessions', private.titan_coach_program_sessions(v_basis->'sessions', (v_basis->>'weeks')::integer));
    insert into private.titan_coach_plans (link_id, coach_id, program_id, program_version, basis, title, goals, start_date, weeks, sessions)
      values (v_link.id, v_uid, coalesce(v_prog.id, (v_basis->>'program_id')::uuid), coalesce(v_prog.version, (v_basis->>'program_version')::integer),
              v_basis - 'program_id' - 'program_version', v_basis->>'title', v_basis->'goals', v_date, (v_basis->>'weeks')::integer, v_basis->'sessions')
      returning * into v_plan;
    return jsonb_build_object('ok', true, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'coach'));
  end if;

  select * into v_plan from private.titan_coach_plans where id = v_id and link_id = v_link.id for update;

  -- edit: the coach adapts the draft for this athlete; the athlete sees nothing before the send.
  if p_action = 'edit' then
    if v_plan.state <> 'draft' then raise exception 'INVALID_TRANSITION' using errcode = '22023'; end if;
    if v_plan.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
    if p_data ? 'title' then
      v_title := left(regexp_replace(btrim(coalesce(p_data->>'title', '')), '[[:cntrl:]<>]', '', 'g'), 100);
      if v_title = '' then raise exception 'BAD_TITLE' using errcode = '22023'; end if;
      v_plan.title := v_title;
    end if;
    if p_data ? 'goals' then v_plan.goals := private.titan_coach_program_goals(p_data->'goals'); end if;
    if p_data ? 'start_date' then
      begin v_date := (p_data->>'start_date')::date; exception when others then raise exception 'INVALID_PERIOD' using errcode = '22023'; end;
      if v_date is null or extract(isodow from v_date) <> 1 or v_date < date_trunc('week', v_today)::date or v_date > v_today + 366 then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
      v_plan.start_date := v_date;
    end if;
    if p_data ? 'weeks' then
      begin v_plan.weeks := (p_data->>'weeks')::integer; exception when others then raise exception 'BAD_SESSIONS' using errcode = '22023'; end;
      if v_plan.weeks is null or v_plan.weeks < 1 or v_plan.weeks > 12 then raise exception 'BAD_SESSIONS' using errcode = '22023'; end if;
    end if;
    v_plan.sessions := private.titan_coach_program_sessions(case when p_data ? 'sessions' then p_data->'sessions' else v_plan.sessions end, v_plan.weeks);
    update private.titan_coach_plans set title = v_plan.title, goals = v_plan.goals, start_date = v_plan.start_date, weeks = v_plan.weeks, sessions = v_plan.sessions,
      revision = revision + 1, updated_at = now() where id = v_plan.id returning * into v_plan;
    return jsonb_build_object('ok', true, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'coach'));
  end if;

  if p_action = 'discard' then
    if v_plan.state <> 'draft' then raise exception 'INVALID_TRANSITION' using errcode = '22023'; end if;
    if v_plan.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
    update private.titan_coach_plans set state = 'discarded', revision = revision + 1, updated_at = now() where id = v_plan.id returning * into v_plan;
    return jsonb_build_object('ok', true, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'coach'));
  end if;

  -- send: the coach's explicit action on the draft they previewed (its revision). Once only: a replay answers « already ».
  if p_action = 'send' then
    if v_plan.state in ('sent', 'closed') then return jsonb_build_object('ok', true, 'already', true, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'coach')); end if;
    if v_plan.state <> 'draft' then raise exception 'INVALID_TRANSITION' using errcode = '22023'; end if;
    if v_plan.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
    if exists (select 1 from jsonb_array_elements(v_plan.sessions) e
                where v_plan.start_date + ((e->>'week')::integer - 1) * 7 + (e->>'day')::integer - 1 not between v_today and v_today + 366) then
      raise exception 'INVALID_PERIOD' using errcode = '22023';
    end if;
    if (select count(*) from public.coach_assignments where link_id = v_link.id) + jsonb_array_length(v_plan.sessions) > 500 then raise exception 'ASSIGNMENT_LIMIT' using errcode = '22023'; end if;
    update private.titan_coach_plans set state = 'sent', sent_at = now(), version = 1, revision = revision + 1, updated_at = now() where id = v_plan.id returning * into v_plan;
    insert into public.coach_assignments (link_id, title, sport, planned_date, instructions, plan_id, plan_key, plan_week)
      select v_link.id, e->>'title', e->>'sport', v_plan.start_date + ((e->>'week')::integer - 1) * 7 + (e->>'day')::integer - 1, coalesce(e->>'instructions', ''),
             v_plan.id, e->>'key', (e->>'week')::integer
        from jsonb_array_elements(v_plan.sessions) e;
    update public.coach_assignments set history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_build_object('k', 'from_plan', 'at', now(), 'plan', v_plan.title, 'week', plan_week, 'weeks', v_plan.weeks)))
     where plan_id = v_plan.id;
    insert into private.titan_coach_plan_versions (plan_id, version, kind, summary, snapshot, actor)
      values (v_plan.id, 1, 'sent', jsonb_build_object('sessions', jsonb_array_length(v_plan.sessions), 'start_date', v_plan.start_date, 'weeks', v_plan.weeks,
                'changes', jsonb_array_length(private.titan_coach_plan_changes(v_plan.basis->'sessions', v_plan.sessions))),
              private.titan_coach_plan_snapshot(v_plan.id), v_uid);
    return jsonb_build_object('ok', true, 'already', false, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'coach'));
  end if;

  -- revise: one occurrence, one week or the rest of the cycle, previewed first (dry_run) then applied with the preview's key.
  -- Done and linked, cancelled, declined (for a week or the rest) and already passed sessions are kept as they are; a session not yet
  -- answered is updated; an accepted one gets a change waiting beside the version in force (V1.9.1), the accepted version stays.
  if p_action = 'revise' then
    if v_plan.state <> 'sent' then raise exception 'INVALID_TRANSITION' using errcode = '22023'; end if;
    v_dry := coalesce((p_data->>'dry_run')::boolean, false);
    if not v_dry then
      begin v_op := (p_data->>'op_id')::uuid; exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
      if v_op is null then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
      select jsonb_build_object('ok', true, 'already', true, 'version', v.version, 'summary', v.summary) into v_e
        from private.titan_coach_plan_versions v where v.plan_id = v_plan.id and v.op_id = v_op;
      if v_e is not null then return v_e || jsonb_build_object('plan', private.titan_coach_plan_row(v_plan, v_link, 'coach')); end if;
    end if;
    v_scope := p_data->>'scope';
    if v_scope is null or v_scope not in ('occurrence', 'week', 'rest') then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
    v_note := nullif(left(btrim(regexp_replace(coalesce(p_data->>'note', ''), '[[:cntrl:]<>]', '', 'g')), 300), '');
    begin v_shift := nullif(p_data->>'shift_days', '')::integer; v_week := nullif(p_data->>'week', '')::integer;
    exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
    v_key := nullif(p_data->>'key', '');
    v_changes := '{}'::jsonb;
    if v_scope = 'occurrence' then
      if v_key is null then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
      if p_data ? 'title' then
        v_title := left(regexp_replace(btrim(coalesce(p_data->>'title', '')), '[[:cntrl:]<>]', '', 'g'), 100);
        if v_title = '' then raise exception 'BAD_TITLE' using errcode = '22023'; end if;
        v_changes := v_changes || jsonb_build_object('title', v_title);
      end if;
      if p_data ? 'sport' then
        if not exists (select 1 from public.sports s where s.id = p_data->>'sport' and coalesce(s.is_active, true)) then raise exception 'SPORT_UNKNOWN' using errcode = '22023'; end if;
        v_changes := v_changes || jsonb_build_object('sport', p_data->>'sport');
      end if;
      if p_data ? 'planned_date' then
        begin v_date := (p_data->>'planned_date')::date; exception when others then raise exception 'INVALID_PERIOD' using errcode = '22023'; end;
        if v_date is null then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
        v_changes := v_changes || jsonb_build_object('planned_date', v_date);
      end if;
      if p_data ? 'instructions' then
        v_changes := v_changes || jsonb_build_object('instructions', left(regexp_replace(coalesce(p_data->>'instructions', ''), '[\x01-\x09\x0b-\x1f\x7f<>]', '', 'g'), 2000));
      end if;
      if v_shift is not null and not v_changes ? 'planned_date' then v_changes := v_changes || jsonb_build_object('shift', v_shift); end if;
      if v_shift is not null and (v_shift < -14 or v_shift > 28) then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
      if v_changes = '{}'::jsonb then raise exception 'CHANGE_EMPTY' using errcode = '22023'; end if;
    else
      if v_week is null or v_week < 1 or v_week > v_plan.weeks then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
      if v_shift is null or v_shift = 0 or v_shift < -14 or v_shift > 28 then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
      -- A week already played is history: it is not revised.
      if v_plan.start_date + v_week * 7 - 1 < v_today then raise exception 'WEEK_PLAYED' using errcode = '22023'; end if;
    end if;
    v_n := 0;
    for v_a in select * from public.coach_assignments a where a.plan_id = v_plan.id
                and (case v_scope when 'occurrence' then a.plan_key = v_key when 'week' then a.plan_week = v_week else a.plan_week >= v_week end)
                order by a.plan_week, a.planned_date, a.plan_key for update loop
      v_n := v_n + 1;
      v_eff := coalesce(v_a.moved_date, v_a.planned_date);
      v_before := private.titan_coach_assignment_version(v_a);
      v_after := v_before || (v_changes - 'shift');
      if v_changes ? 'shift' then v_after := v_after || jsonb_build_object('planned_date', v_a.planned_date + (v_changes->>'shift')::integer); end if;
      if v_scope <> 'occurrence' then v_after := v_before || jsonb_build_object('planned_date', v_a.planned_date + v_shift); end if;
      v_effect := case
        when v_a.status = 'completed' then 'kept_done'
        when v_a.status = 'cancelled' then 'kept_cancelled'
        when v_scope <> 'occurrence' and v_a.status = 'declined' then 'kept_declined'
        when v_scope <> 'occurrence' and v_eff < v_today then 'kept_past'
        when (v_after->>'planned_date')::date < v_today or (v_after->>'planned_date')::date > v_today + 366 then 'kept_out_of_range'
        when v_after = v_before then 'unchanged'
        when v_a.status = 'proposed' then 'updated'
        else 'change_proposed' end;
      if v_scope = 'occurrence' and v_effect = 'kept_out_of_range' then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
      v_effects := v_effects || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('key', v_a.plan_key, 'week', v_a.plan_week, 'id', v_a.id, 'title', v_a.title,
        'status', v_a.status, 'effect', v_effect, 'before', v_before, 'after', case when v_effect in ('updated', 'change_proposed') then v_after else null end,
        'linked', v_a.session_id is not null, 'revision', v_a.revision)));
    end loop;
    if v_n = 0 then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
    v_preview := left(md5(v_effects::text || coalesce(v_note, '')), 16);
    v_summary := jsonb_build_object('scope', v_scope, 'key', v_key, 'week', v_week, 'shift_days', v_shift, 'note', v_note,
      'fields', (select coalesce(jsonb_agg(k order by k), '[]'::jsonb) from jsonb_object_keys(v_changes - 'shift') k),
      'counts', (select coalesce(jsonb_object_agg(x, n), '{}'::jsonb) from (select e->>'effect' x, count(*) n from jsonb_array_elements(v_effects) e group by 1) q));
    if v_dry then
      return jsonb_build_object('ok', true, 'dry_run', true, 'preview_key', v_preview, 'effects', v_effects, 'summary', jsonb_strip_nulls(v_summary));
    end if;
    if v_preview is distinct from p_data->>'preview_key' then raise exception 'COACH_CONFLICT'; end if;
    if not exists (select 1 from jsonb_array_elements(v_effects) e where e->>'effect' in ('updated', 'change_proposed')) then raise exception 'CHANGE_EMPTY' using errcode = '22023'; end if;
    for v_e in select e from jsonb_array_elements(v_effects) e where e->>'effect' in ('updated', 'change_proposed') loop
      select * into v_a from public.coach_assignments where id = (v_e->>'id')::uuid;
      if v_e->>'effect' = 'updated' then
        update public.coach_assignments set title = v_e#>>'{after,title}', sport = v_e#>>'{after,sport}', planned_date = (v_e#>>'{after,planned_date}')::date,
            instructions = coalesce(v_e#>>'{after,instructions}', ''), discuss_note = null, discuss_at = null, coach_seen_key = null, revision = revision + 1, updated_at = now(),
            history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('k', 'plan_revised', 'at', now(), 'before', v_e->'before',
                        'after', v_e->'after', 'scope', v_scope, 'plan_version', v_plan.version + 1, 'note', v_note))))
         where id = v_a.id;
      else
        update public.coach_assignments set pending_change = jsonb_strip_nulls((v_e->'after') || jsonb_build_object('note', v_note, 'at', now(), 'from_status', v_a.status, 'plan_version', v_plan.version + 1)),
            revision = revision + 1, updated_at = now(), coach_seen_key = null,
            history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('k', case when v_a.pending_change is null then 'change_proposed' else 'change_replaced' end,
                        'at', now(), 'before', v_e->'before', 'after', v_e->'after', 'note', v_note, 'scope', v_scope, 'plan_version', v_plan.version + 1))))
         where id = v_a.id;
      end if;
    end loop;
    v_summary := jsonb_strip_nulls(v_summary - 'counts') || jsonb_build_object('counts', (select coalesce(jsonb_object_agg(x, n), '{}'::jsonb) from (select e->>'effect' x, count(*) n from jsonb_array_elements(v_effects) e group by 1) q),
      'effects', (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('key', e->>'key', 'week', e->'week', 'effect', e->>'effect', 'from', e#>>'{before,planned_date}', 'to', e#>>'{after,planned_date}'))), '[]'::jsonb) from jsonb_array_elements(v_effects) e));
    update private.titan_coach_plans set version = version + 1, revision = revision + 1, updated_at = now() where id = v_plan.id returning * into v_plan;
    insert into private.titan_coach_plan_versions (plan_id, version, kind, op_id, scope, summary, snapshot, actor)
      values (v_plan.id, v_plan.version, 'revision', v_op, v_scope, v_summary, private.titan_coach_plan_snapshot(v_plan.id), v_uid);
    return jsonb_build_object('ok', true, 'already', false, 'version', v_plan.version, 'summary', v_summary, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'coach'));
  end if;

  -- answer: the athlete accepts, declines or asks to discuss proposed sessions, and accepts or keeps their version for changes waiting.
  -- A session already decided is left as it is (« unchanged »): replaying the same answers changes nothing.
  if p_action = 'answer' then
    if v_plan.state <> 'sent' then raise exception 'INVALID_TRANSITION' using errcode = '22023'; end if;
    if p_data->>'all' is not null and p_data->>'all' <> 'accept' then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
    if p_data->>'all' is null and (jsonb_typeof(p_data->'decisions') is distinct from 'array' or jsonb_array_length(p_data->'decisions') = 0 or jsonb_array_length(p_data->'decisions') > 60) then
      raise exception 'INVALID_INPUT' using errcode = '22023';
    end if;
    for v_a in select * from public.coach_assignments a where a.plan_id = v_plan.id
                and (p_data->>'all' is not null or a.plan_key in (select e->>'key' from jsonb_array_elements(p_data->'decisions') e))
                order by a.plan_week, a.planned_date, a.plan_key for update loop
      if p_data->>'all' is not null then v_answer := case when v_a.pending_change is not null then 'accept_change' else 'accept' end; v_note := null;
      else
        select e->>'answer', nullif(left(btrim(regexp_replace(coalesce(e->>'note', ''), '[[:cntrl:]<>]', '', 'g')), 300), '') into v_answer, v_note
          from jsonb_array_elements(p_data->'decisions') e where e->>'key' = v_a.plan_key limit 1;
      end if;
      if v_answer is null or v_answer not in ('accept', 'decline', 'discuss', 'accept_change', 'keep_version') then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
      v_effect := 'unchanged';
      if v_answer in ('accept', 'decline') and v_a.status = 'proposed' then
        update public.coach_assignments set status = case when v_answer = 'accept' then 'accepted' else 'declined' end, discuss_note = null, discuss_at = null,
          revision = revision + 1, updated_at = now() where id = v_a.id returning * into v_a;
        v_effect := case when v_answer = 'accept' then 'accepted' else 'declined' end;
      elsif v_answer = 'discuss' and v_a.status = 'proposed' and v_a.discuss_note is distinct from v_note then
        update public.coach_assignments set discuss_note = v_note, discuss_at = now(), revision = revision + 1, updated_at = now(),
          history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('k', 'discuss', 'at', now(), 'note', v_note))))
         where id = v_a.id returning * into v_a;
        v_effect := 'to_discuss';
      elsif v_answer in ('accept_change', 'keep_version') and v_a.pending_change is not null and v_a.status in ('accepted', 'declined') then
        v_a := private.titan_coach_apply_change(v_a.id, v_answer = 'accept_change');
        v_effect := case when v_answer = 'accept_change' then 'change_accepted' else 'version_kept' end;
      end if;
      v_results := v_results || jsonb_build_array(jsonb_build_object('key', v_a.plan_key, 'answer', v_answer, 'effect', v_effect, 'status', v_a.status));
    end loop;
    if p_data->>'all' is null and jsonb_array_length(v_results) <> (select count(distinct e->>'key') from jsonb_array_elements(p_data->'decisions') e) then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
    return jsonb_build_object('ok', true, 'results', v_results, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'athlete'));
  end if;

  -- close: the end of the cycle. Sessions still waiting for an answer are cancelled, changes still waiting are withdrawn; what the
  -- athlete accepted or did stays theirs. The closing version keeps the final picture.
  if v_plan.state = 'closed' then return jsonb_build_object('ok', true, 'already', true, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'coach')); end if;
  if v_plan.state <> 'sent' then raise exception 'INVALID_TRANSITION' using errcode = '22023'; end if;
  if v_plan.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
  perform 1 from public.coach_assignments where plan_id = v_plan.id for update;
  select jsonb_build_object('cancelled', count(*) filter (where status = 'proposed'), 'withdrawn', count(*) filter (where pending_change is not null and status <> 'proposed'),
           'accepted', count(*) filter (where status = 'accepted'), 'linked', count(*) filter (where session_id is not null), 'declined', count(*) filter (where status = 'declined'))
    into v_e from public.coach_assignments where plan_id = v_plan.id;
  update public.coach_assignments set status = 'cancelled', discuss_note = null, discuss_at = null, revision = revision + 1, updated_at = now() where plan_id = v_plan.id and status = 'proposed';
  update public.coach_assignments set pending_change = null, revision = revision + 1, updated_at = now(),
    history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_build_object('k', 'change_withdrawn', 'at', now(), 'plan_closed', true)))
   where plan_id = v_plan.id and pending_change is not null;
  update private.titan_coach_plans set state = 'closed', closed_at = now(), version = version + 1, revision = revision + 1, updated_at = now() where id = v_plan.id returning * into v_plan;
  insert into private.titan_coach_plan_versions (plan_id, version, kind, summary, snapshot, actor)
    values (v_plan.id, v_plan.version, 'closed', v_e, private.titan_coach_plan_snapshot(v_plan.id), v_uid);
  return jsonb_build_object('ok', true, 'already', false, 'plan', private.titan_coach_plan_row(v_plan, v_link, 'coach'));
end;
$function$;
revoke all on function public.titan_coach_program_v1(text, jsonb) from public, anon;
grant execute on function public.titan_coach_program_v1(text, jsonb) to authenticated;

-- ---- The export: the body of 20261203090000, plus the coach's templates and programmes (their own working content) and, for both sides
-- of a link, the programmes sent (what was proposed and its versions; no measure of the athlete).
create or replace function private.titan_export_extras_v1(p_uid uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select private.titan_export_extras_before_cadence_v1(p_uid) || jsonb_build_object(
    'cadenceWeekClaims', coalesce((
      select jsonb_agg(jsonb_build_object('week', c.week_start, 'days', c.days, 'target', c.target, 'credits', c.credits, 'claimed_at', c.claimed_at) order by c.week_start)
      from private.titan_cadence_claims c where c.user_id = p_uid), '[]'::jsonb),
    'timeCapsules', coalesce((
      select jsonb_agg(jsonb_build_object('message', t.message, 'months', t.months, 'deliver_on', t.deliver_on, 'written_minutes', t.written_minutes,
        'written_days', t.written_days, 'created_at', t.created_at, 'opened_at', t.opened_at) order by t.created_at)
      from private.titan_time_capsules t where t.user_id = p_uid), '[]'::jsonb),
    'lifeChapters', coalesce((
      select jsonb_agg(jsonb_build_object('title', l.title, 'starts_on', l.starts_on, 'ends_on', l.ends_on, 'created_at', l.created_at) order by l.starts_on)
      from private.titan_life_chapters l where l.user_id = p_uid), '[]'::jsonb),
    'coachFeedback', coalesce((
      select jsonb_agg(jsonb_build_object('link_id', f.link_id, 'assignment_id', f.assignment_id, 'message_id', f.message_id, 'session_day', f.session_day,
        'adjustment', f.adjustment, 'adjustment_state', f.adjustment_state, 'answered_at', f.answered_at, 'read_at', f.read_at, 'created_at', f.created_at) order by f.created_at)
      from private.titan_coach_feedback f join public.coach_links l on l.id = f.link_id where p_uid in (l.coach_id, l.athlete_id)), '[]'::jsonb),
    'coachReviewDrafts', coalesce((
      select jsonb_agg(jsonb_build_object('link_id', d.link_id, 'week', d.week_start, 'state', d.state, 'basis', d.basis - 'base', 'content', d.content,
        'assignment_id', d.assignment_id, 'created_at', d.created_at, 'sent_at', d.sent_at) order by d.created_at)
      from private.titan_coach_review_drafts d where d.coach_id = p_uid), '[]'::jsonb),
    'coachPrograms', coalesce((
      select jsonb_agg(jsonb_build_object('title', g.title, 'version', g.version, 'archived_at', g.archived_at, 'created_at', g.created_at,
        'versions', (select jsonb_agg(jsonb_build_object('version', v.version, 'weeks', v.weeks, 'goals', v.goals, 'sessions', v.sessions, 'created_at', v.created_at) order by v.version)
                       from private.titan_coach_program_versions v where v.program_id = g.id)) order by g.created_at)
      from private.titan_coach_programs g where g.coach_id = p_uid), '[]'::jsonb),
    'coachPlans', coalesce((
      select jsonb_agg(jsonb_build_object('link_id', p.link_id, 'title', p.title, 'goals', p.goals, 'start_date', p.start_date, 'weeks', p.weeks, 'state', p.state,
        'sessions', case when p.coach_id = p_uid or p.state in ('sent', 'closed') then p.sessions else null end, 'created_at', p.created_at, 'sent_at', p.sent_at, 'closed_at', p.closed_at,
        'versions', (select jsonb_agg(jsonb_build_object('version', v.version, 'kind', v.kind, 'scope', v.scope, 'summary', v.summary, 'snapshot', v.snapshot, 'created_at', v.created_at) order by v.version)
                       from private.titan_coach_plan_versions v where v.plan_id = p.id)) order by p.created_at)
      from private.titan_coach_plans p join public.coach_links l on l.id = p.link_id
     where p.coach_id = p_uid or (l.athlete_id = p_uid and p.state in ('sent', 'closed'))), '[]'::jsonb));
$$;
revoke all on function private.titan_export_extras_v1(uuid) from public, anon, authenticated;

-- Measure (team only, no identifier): templates and versions, programmes by state, the preparation time of a programme (draft created
-- → sent), the cycles revised and whether every version is still there, and how the athletes answered.
create or replace function private.titan_coach_program_measure()
returns jsonb language sql stable security definer set search_path = ''
as $function$
  select jsonb_build_object(
    'programs', (select count(*) from private.titan_coach_programs),
    'programVersions', (select count(*) from private.titan_coach_program_versions),
    'plans', (select coalesce(jsonb_object_agg(s, n), '{}'::jsonb) from (select state s, count(*) n from private.titan_coach_plans group by 1) x),
    'prepMinutesMedian', (select round((percentile_cont(0.5) within group (order by extract(epoch from sent_at - created_at) / 60.0))::numeric, 1) from private.titan_coach_plans where sent_at is not null),
    'prepMinutesMax', (select round(max(extract(epoch from sent_at - created_at) / 60.0)::numeric, 1) from private.titan_coach_plans where sent_at is not null),
    'revisions', (select count(*) from private.titan_coach_plan_versions where kind = 'revision'),
    'plansRevised', (select count(distinct plan_id) from private.titan_coach_plan_versions where kind = 'revision'),
    'plansRevisedWithHistory', (select count(*) from (select plan_id from private.titan_coach_plan_versions group by plan_id
                                  having bool_or(kind = 'revision') and count(*) = max(version) and min(version) = 1) h),
    'sessions', (select count(*) from public.coach_assignments where plan_id is not null),
    'accepted', (select count(*) from public.coach_assignments where plan_id is not null and status in ('accepted', 'completed')),
    'linked', (select count(*) from public.coach_assignments where plan_id is not null and session_id is not null),
    'toDiscuss', (select count(*) from public.coach_assignments where plan_id is not null and status = 'proposed' and discuss_at is not null))
$function$;
revoke all on function private.titan_coach_program_measure() from public, anon, authenticated;

notify pgrst, 'reload schema';
-- <<< repository file
insert into supabase_migrations.schema_migrations (version, name) values ('20261204090000', 'coach_programs');
commit;
